def cached_value(cache, key, load):
    if key not in cache:
        cache[key] = load(key)
    return cache[key]

def dispatch(request, send, retry):
    if request.idempotent:
        return retry(send, request)
    return send(request)

class Invoice {
    java.math.BigDecimal displayAmount(java.math.BigDecimal amount) {
        return amount.setScale(2, java.math.RoundingMode.HALF_UP);
    }
}

class Access {
    boolean visible(boolean publicProject, boolean administrator, String userId, String ownerId) {
        return publicProject || administrator || userId.equals(ownerId);
    }
}

def batches(items, size):
    for start in range(0, len(items), size):
        yield items[start:start + size]

def withdraw(balance, amount):
    if amount <= balance:
        return balance - amount
    raise ValueError('insufficient funds')
